import * as OurTypes from "../src/types";
import * as TestCommonJsonization from "./commonJsonization";

test("casts over an instance of Item", () => {
  const theItem =
    TestCommonJsonization.loadMinimalItem();

  expect(
    OurTypes.isItem(theItem)
  ).toStrictEqual(true);
  expect(
    OurTypes.asItem(theItem)
  ).toStrictEqual(theItem);

  expect(
    OurTypes.isSomething(theItem)
  ).toStrictEqual(false);
  expect(
    OurTypes.asSomething(theItem)
  ).toBeNull();
});

test("casts over an instance of Something", () => {
  const theSomething =
    TestCommonJsonization.loadMinimalSomething();

  expect(
    OurTypes.isItem(theSomething)
  ).toStrictEqual(false);
  expect(
    OurTypes.asItem(theSomething)
  ).toBeNull();

  expect(
    OurTypes.isSomething(theSomething)
  ).toStrictEqual(true);
  expect(
    OurTypes.asSomething(theSomething)
  ).toStrictEqual(theSomething);
});

